const campaignCardVi = {
 '01105': ['Chuyện gì đang xảy ra?!', '', 'Đêm đã khuya. Bạn cố thủ trong Study để tìm hiểu những vụ mất tích đẫm máu trong vùng. Vài giờ trôi qua, tiếng tụng niệm kỳ quái vọng từ Parlor cuối hành lang. Cùng lúc đó, đất dưới sàn xáo động như thể có thứ gì đang đào lên.',
  'Khoảng thời gian bị mất', 'Trưởng nhóm chọn một: mỗi điều tra viên bỏ ngẫu nhiên 1 lá trên tay, hoặc trưởng nhóm nhận 2 horror.', 'Ngôi nhà tiếp tục biến đổi ngay trước mắt bạn. Tường mục rữa, nền nhiều phòng hóa thành đất. Cứ như bạn đã bị đưa tới một nơi khác, dù thỉnh thoảng vẫn nhận ra vài dấu tích của ngôi nhà cũ.'],
 '01106': ['Bầy Ghoul trỗi dậy', '', 'Sàn nhà sụp xuống, để lộ cả một mạng đường hầm ngoằn ngoèo chìm trong bóng tối. Những bóng hình kỳ dị lao vun vút qua các đường hầm, tìm lối trồi lên. Tốt hơn hết bạn nên rời đi trước khi chúng tìm thấy lối.',
  'Những đường hầm bên dưới', 'Xào encounter discard pile vào encounter deck. Bỏ từng lá trên cùng cho đến khi bỏ một kẻ địch [[Ghoul]]. Trưởng nhóm rút lá kẻ địch đó.', 'Một con thú hoang dáng người, mõm chó và chân có móng guốc xé tung mặt đất trước mặt bạn. Dưới sàn là những đường hầm mênh mông. Tiếng tru man dại vọng lên từ sâu trong lòng đất.'],
 '01107': ['Chúng đang thoát ra!', 'Bắt buộc — Cuối pha kẻ địch: Mỗi kẻ địch [[Ghoul]] chưa giao chiến di chuyển 1 vị trí về phía Parlor.\nBắt buộc — Cuối vòng: Đặt 1 doom lên Agenda này cho mỗi kẻ địch [[Ghoul]] ở Hallway hoặc Parlor.', 'Một tiếng tru điên dại vang lên bên ngoài. Lũ sinh vật lập tức lao ra khỏi nhà, phá cửa và cào xé mọi thứ chắn đường.',
  'Bầy Ghoul thoát ra', 'Nếu các điều tra viên đang ở Act 1 hoặc 2, họ mắc kẹt trong nhà và bị bầy Ghoul xé xác (→R3).\nNếu đang ở Act 3, họ thoát chết trong gang tấc và để bầy Ghoul chạy khắp nơi. Mỗi điều tra viên chưa rút lui bị đánh bại và nhận 1 physical trauma.', 'Mặt đất rung chuyển. Vuốt nhọn trồi lên khắp nơi khi những sinh vật quái dị cố cào đường thoát khỏi lòng đất. Kinh hãi, bạn bỏ chạy hết sức.'],
 '01108': ['Mắc kẹt', '', 'Bạn bật dậy định đi xem thì cửa Study biến mất ngay trước mắt, chỉ còn một bức tường đặc. Bạn mắc kẹt cho đến khi tìm được lối khác.',
  'Cánh cửa dưới sàn', 'Đưa Hallway, Cellar, Attic và Parlor đã để riêng vào chơi.\nBỏ mọi kẻ địch trong Study.\nĐặt mỗi điều tra viên tại Hallway.\nLoại Study khỏi ván chơi.', 'Mép tấm thảm mới mua đã tưa ra và lấm bùn. Bạn dời đồ đạc, lật thảm lên và thấy chính cánh cửa dẫn ra khỏi Study. Bạn xoay tay nắm, để lộ hành lang phía dưới.\nBạn nhảy xuống nền đất mềm. Cánh cửa sập lại trên đầu. Mùi gỗ cháy quyện với mùi mục rữa trong hành lang hẹp.'],
 '01109': ['Rào chắn', 'Mục tiêu — Cuối vòng, các điều tra viên ở Hallway có thể cùng chi đủ số manh mối yêu cầu để tiến Act.', 'Một rào chắn phát sáng chặn lối vào Parlor. Sức nóng buộc bạn lùi lại. Bạn ném một nắm đất vào đó và kinh hãi nhìn nó cháy rụi. Có lẽ Cellar hoặc Attic có thứ hữu ích.',
  'Phá rào chắn', 'Rào chắn trước Parlor biến mất. Lật Parlor.\nĐưa Lita Chantler đã để riêng vào chơi tại Parlor.\nCho Ghoul Priest đã để riêng xuất hiện tại Hallway.', 'Bạn dùng chiếc thùng trên gác để mang băng tuyết từ tầng hầm lên, rồi hắt vào rào chắn. Nó tóe lửa, rung bần bật, rít lên rồi tan biến.'],
 '01110': ['Bạn đã làm gì vậy?', 'Mục tiêu — Khi Ghoul Priest bị đánh bại, tiến Act.', 'Một phụ nữ cầm đuốc đứng trong Parlor, ánh mắt đầy căm giận. “Ngươi đã làm gì rào chắn của ta?” cô hét lên. Trước khi bạn kịp bước vào, một tiếng rú vang sau lưng. Một sinh vật khoác áo choàng, đeo sọ hươu, xé toạc tường và tiến về phía bạn.',
  'Bảo vệ ngôi nhà', 'Trưởng nhóm chọn một:\n- Nơi này có đáng gọi là nhà đâu. Đốt đi! (→R1)\n- Cái ổ địa ngục này là nhà tôi! Tuyệt đối không đốt! (→R2)', 'Khi con quái vật khoác áo choàng gục xuống, cả bầy chui trở lại lòng đất. Ngôi nhà lặng đi, nhưng người lạ trong Parlor chẳng hề nhẹ nhõm.\n“Ngươi phá phong ấn ta dùng để nhốt lũ Ghoul rồi.” Cô giơ cao ngọn đuốc. “Giờ chỉ còn cách thiêu rụi cái ổ địa ngục này!”'],
 '01121a': ['Thợ săn hay con mồi?', '[action]: Rút lui. Bạn lui về nơi an toàn với thông tin đã thu thập được.', 'Lita tin rằng có một âm mưu ngay trong Arkham. Một giáo phái bí mật phụng sự lũ Ghoul dưới các hầm mộ, và những thành viên chủ chốt của chúng đang tản khắp thành phố. Khi lần theo chúng, bạn không sao gạt được cảm giác chính mình cũng đang bị săn đuổi.'],
 '01121b': ['The Masked Hunter', 'Xuất hiện — Giao chiến với mục tiêu Prey.\nPrey — Người có nhiều manh mối nhất.\nHunter.\nThe Masked Hunter được +2 sức khỏe mỗi điều tra viên.\nKhi đang giao chiến với The Masked Hunter, bạn không thể tìm hoặc chi manh mối.'],
 '01122': ['Thời gian sắp hết', '[action]: Rút lui. Bạn lui về nơi an toàn với thông tin đã thu thập được.', 'Từng phút trôi nhanh khi cuộc điều tra tiếp diễn.',
  'Đồng hồ điểm nửa đêm', '(→R2)', 'Mười hai tiếng chuông vang khắp thành phố. Đã nửa đêm. Bạn phải hành động dựa trên những gì đã moi được từ đám giáo đồ.'],
 '01123': ['Vạch trần âm mưu', '[action] Cả nhóm cùng chi 2 manh mối mỗi điều tra viên: Rút lá trên cùng của Cultist deck.\nMục tiêu — Đưa càng nhiều kẻ địch [[Cultist]] khác nhau vào victory display càng tốt. Khi đủ 6 tên, tiến Act. Một số tên nằm ngoài Cultist deck.', 'Bạn có một đêm để tìm các thành viên giáo phái và vạch trần kế hoạch của chúng. Hãy tìm và thẩm vấn càng nhiều tên càng tốt trước nửa đêm.',
  'Bí mật phơi bày', '(→R1)', 'Bạn đã nhận diện đủ những kẻ cầm đầu giáo phái ở Arkham. Kẻ bám đuôi bạn và Herman, người trông coi nghĩa địa, đều là tín đồ cuồng nhiệt. Những người khác bị ép buộc. Ruth phải cung cấp xác chết để giữ mạng cho gia đình, và bạn đã giúp cô thoát khỏi bệnh viện. Peter phải được thuyết phục rằng giúp giáo phái chỉ gây thêm tai họa. Nỗi ám ảnh với cổ vật đã kéo Victoria vào lưới của chúng. Drew tấn công bạn ở nhà thương điên vì tưởng bạn là người của giáo phái. Càng đào sâu, bạn càng thấy âm mưu này đã hủy hoại biết bao cuộc đời.'],
 '01143': ['Rừng Arkham', '', 'Qua thẩm vấn, bạn biết giáo phái đang làm lễ báo thù vì một hang ổ của chủ nhân chúng đã bị phá. Bạn tiến vào khu rừng ngoài Arkham để ngăn chúng. Khu rừng lạnh khác thường và im lìm như cõi chết.',
  'Giết kẻ xâm nhập', 'Xào encounter discard pile vào encounter deck rồi bỏ từng lá trên cùng cho đến khi bỏ một kẻ địch [[Monster]]. Cho nó xuất hiện tại Main Path, rồi đặt 1 doom lên nó.', 'Một tiếng thét chói tai vọng khắp rừng. Từ sâu bên trong, hàng chục giọng gào ghê rợn đáp lại. Chúng tru như chó săn mà vẫn phát âm rõ một cái tên: “Umôrdhoth… Umôrdhoth… Umôrdhoth…”'],
 '01144': ['Nghi lễ bắt đầu', 'Mỗi kẻ địch được +1 fight và +1 evade.', '“Umôrdhoth… Umôrdhoth… Umôrdhoth…”\nTiếng tụng mỗi lúc một lớn, dội vào không khí lạnh buốt. Mây tụ trên rừng Arkham, che lấp cả ánh sao leo lét.',
  'Ý chí của Umôrdhoth', 'Theo thứ tự người chơi, mỗi điều tra viên kiểm tra [willpower] (6). Ai thất bại lấy ngẫu nhiên 1 điểm yếu cơ bản [[Madness]] từ bộ sưu tập và thêm vào tay.', 'Một hiện diện đen tối tiến đến. Sức ép vô hình buộc bạn quỳ sụp. Một thế lực kinh hoàng chực xâm chiếm tâm trí và linh hồn bạn. Cổ họng thắt lại, mắt cay xè khi cảm giác ấy thiêu đốt khắp người.'],
 '01145': ['Báo thù cận kề', 'Bắt buộc — Khi Agenda này tiến:\n- Nếu đang ở Act 1, đưa Ritual Site vào chơi và cho Umôrdhoth xuất hiện tại đó.\n- Nếu đang ở Act 2 hoặc 3, bỏ mọi kẻ địch tại Ritual Site rồi cho Umôrdhoth xuất hiện ở đó.', 'Thế giới biến dạng khi nghi lễ gần hoàn tất. Không khí lạnh buốt, sương giá phủ kín rừng. Cây cối oằn mình, đổ những cái bóng dài méo mó.',
  'The Devourer Below', 'Tiết lộ — Thay Act và Agenda hiện tại bằng The Devourer Below. Lá này đồng thời là Act và Agenda hiện tại.\nMục tiêu — Nếu Umôrdhoth bị đánh bại, chuyển sang R2.'],
 '01146': ['Lần theo dấu vết', '', 'Bằng chứng dẫn bạn đến rừng phía nam Arkham, nơi sắp diễn ra nghi lễ triệu hồi một thực thể tên Umôrdhoth. Bạn lấy hết can đảm tiến sâu vào rừng để tìm nơi hành lễ.',
  'Hé lộ kế hoạch', 'Đưa Ritual Site đã để riêng vào chơi nếu chưa có.\nTìm từng kẻ địch trong mục “Giáo đồ trốn thoát” của Nhật ký Chiến dịch và cho chúng xuất hiện tại Main Path.', 'Ký hiệu huyền bí khắc trên vỏ cây, mặt đá, thậm chí vẽ bằng máu trên đất. Bạn không giải mã được chúng, nhưng nhận thấy hầu hết đều hướng nam. Theo dấu ấy, bạn tới một hang động ở nơi tối tăm và lạnh lẽo nhất khu rừng.\nNhững bóng đen bước ra khỏi hàng cây, chắn lối duy nhất vào hang.'],
 '01147': ['Vào bóng tối', 'Mục tiêu — Khi một điều tra viên vào Ritual Site, tiến Act.', 'Những giáo đồ còn lại đã theo bạn vào rừng. Chúng đứng im dưới tán cây, chắn đường như lính gác trong đêm. Bạn phải đánh bại hoặc lẻn qua chúng để tới nơi hành lễ.',
  'Nghi thức cuối cùng', 'Xào encounter discard pile vào encounter deck. Bỏ từng lá trên cùng đến khi bỏ 1 kẻ địch (2 nếu có từ 3 người chơi). Cho mỗi kẻ địch vừa bỏ xuất hiện tại Ritual Site.', 'Vừa vào hang, bạn đã thấy không khí lạnh hẳn. Mùi máu và mùi thối rữa xộc vào mũi.'],
 '01148': ['Phá nghi lễ', '[action] Chi 1 manh mối: Kiểm tra [willpower] (3) hoặc [agility] (3). Thành công: Đặt 1 manh mối lên Act này.\nMục tiêu — Khi có 2 manh mối mỗi điều tra viên trên Act này, tiến Act.', 'Giáo phái hành lễ trong một hang lớn ở góc tối của khu rừng. Chính giữa hang là vòng tròn thắp nến, viền bằng đá và những ký tự huyền bí.',
  'Nghi lễ tan vỡ', '(→R1)', 'Bạn chống chọi với cái lạnh kỳ dị, lách qua những ký hiệu và bước vào vòng tròn. Bạn vùi các dấu vẽ dưới đất và phá tung những viên đá được xếp tỉ mỉ. Một âm thanh chói tai vang lên. Không khí đột ngột ấm lại, thế giới méo đi rồi trở về bình thường.']
};

export function campaignCardFace(card, back = false) {
 const vi = campaignCardVi[card.code];
 if (vi) {
  const [name, text, flavor] = back ? vi.slice(3) : vi;
  if (name) return {name, text, flavor};
 }
 return back
  ? {name: card.back_name ?? card.name, text: card.back_text, flavor: card.back_flavor}
  : card;
}
